B = {"l": "left", "c": "center", "r": "right"}
PERMS = ["lcr", "lrc", "clr", "crl", "rlc", "rcl"]

def main(out):
    rows = []
    seen = set()
    for i, (cat, code, text) in enumerate(ITEMS, 1):
        assert sorted(code) == ["c", "l", "r"], (i, code)
        assert text not in seen, text
        seen.add(text)
        rows.append({"id": f"t2a-{i:03d}", "text": text, "category": cat,
                     "spec": {"mapping": {"red": B[code[0]], "yellow": B[code[1]], "blue": B[code[2]]}}})
    with open(out, "w") as f:
        for r in rows:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    cats = collections.Counter(c for c, _, _ in ITEMS)
    print("total", len(ITEMS), dict(cats))
    main_perm = collections.Counter(code for c, code, _ in ITEMS if c != "real_colour_names")
    print("main perms", {p: main_perm[p] for p in PERMS}, "main n", sum(main_perm.values()))
    print("real perms", dict(collections.Counter(code for c, code, _ in ITEMS if c == "real_colour_names")))
    for cat in cats:
        print(cat, {p: sum(1 for c, code, _ in ITEMS if c == cat and code == p) for p in PERMS})

if __name__ == "__main__":
    main(sys.argv[1])
